import {morph} from './morph.js'

const keyHint=(s,action)=>K(...keyParts(keyBindings(s.prefs)[action]))
const button=(a,label,cls='btn sm')=>`<button type="button" class="${cls}" data-a="${a}">${label}</button>`
const alert=s=>s.error?`<div class="form-alert" role="alert">${esc(s.error)}</div>`:s.notice?`<div class="form-notice" role="status">${esc(s.notice)}</div>`:''
const field=(name,label,type,placeholder,value='',extra='')=>`<label><span class="lbl">${label}</span><div class="inp"><input id="${name}" name="${name}" type="${type}" placeholder="${placeholder}" value="${esc(value)}" ${extra}></div></label>`
const deco=`<div class="reg h" style="top:170px"></div><div class="reg h" style="top:730px"></div><div class="reg v" style="left:96px"></div><div class="reg v" style="right:96px"></div><div class="dots decor-dots left"></div><div class="dots decor-dots right"></div>`
function shell(title,lines,body,foot='',connect=false) {
  return `<main class="scr ${connect?'link-screen':''}">${deco}<a class="brand" href="/" aria-label="Terminal Mail home"><span class="sq"></span>TERMINAL_MAIL</a><div class="auth-layout"><div class="crop auth-hero"><h1 class="hl">${title}</h1><div class="prm big">${lines.map(l=>`<div>${l}</div>`).join('')}</div></div><div class="auth-window">${body}</div></div><div class="foot"><span>mail.microapps.space</span><span>${foot}</span></div></main>`
}
export function authView(s) {
  const mode=s.mode
  const content={
    login:['SYSTEM_STATUS: LOCKED',['IDENTITY: REQUIRED //','MAILBOX: ENCRYPTED //','AGENTS: STANDING_BY'],'AUTH.SYS','SIGN_IN'],
    register:['NEW_OPERATOR: ENROLL',['INVITE_ONLY_DOMAINS //','VERIFICATION: EMAIL //','PASSWORD: SCRYPT'],'REGISTER.SYS','CREATE_ACCOUNT'],
    verify:['LINK_SENT: CHECK_INBOX',[`TO: ${esc(s.authEmail)} //`,'EXPIRES: 30 MIN //','SINGLE_USE: TRUE'],'VERIFY.SYS','RESEND_LINK'],
    forgot:['CREDENTIAL_RESET',['IDENTITY: EMAIL //','LINK: SINGLE_USE //','EXPIRES: 30 MIN'],'RESET.SYS','SEND_RESET_LINK'],
    reset:['CREDENTIAL_RESET',['ALL_SESSIONS: REVOKED //','MCP_TOKENS: REVOKED //','ICLOUD_LINK: KEPT'],'RESET.SYS','SET_PASSWORD'],
  }[mode]
  const [h,l,title,cta]=content
  let fields=''
  if(mode!=='reset'&&mode!=='verify')fields+=field('email','Email','email','you@olegpustovit.com',s.authEmail,'required autocomplete="email"')
  if(['login','register','reset'].includes(mode))fields+=field('password',mode==='reset'?'New password':mode==='register'?'Password · 12+':'Password','password',mode==='login'?'Your password':'At least 12 characters',s.authPassword,`required maxlength="128" ${mode==='login'?'':'minlength="12"'} autocomplete="${mode==='login'?'current-password':'new-password'}"`)
  if(mode==='verify')fields+=`<div class="dots" style="height:110px;border:var(--frame);display:grid;place-items:center;font-size:44px">${ico('mail')}</div>`
  const alt=mode==='login'?button('auth:register','REGISTER','link')+button('auth:forgot','FORGOT','link'):button('auth:login',mode==='verify'?'DIFFERENT EMAIL':'BACK TO SIGN IN','link')
  return shell(h,l,W(title,`<form id="auth-form" class="form-grid">${alert(s)}${fields}<button class="btn pri lg wide" style="justify-content:center" ${s.busy?'disabled':''}>${s.busy?'PLEASE_WAIT':cta} ${K('↵')}</button><div class="form-links">${alt}</div></form>`,{on:1,cls:'pop',a:'auth'}))
}
export function connectView(s) {
  const body=W('LINK_ICLOUD.SYS // STEP 2 OF 3',`<form id="link-form" class="form-grid">${alert(s)}${field('icloud-email','iCloud address','email','you@icloud.com',s.icloudEmail,'required autocomplete="email"')}${field('icloud-password','App-specific password','password','xxxx-xxxx-xxxx-xxxx','','required autocomplete="new-password"')}<button class="btn pri lg wide" style="justify-content:center" ${s.busy?'disabled':''}>${s.busy?'TESTING_CONNECTION':s.error?'RETRY':'TEST_AND_LINK'} ${K('↵')}</button>${s.account?.connected?button('mail','BACK TO MAIL','link'):button('logout','SIGN OUT','link')}</form>`,{on:1,cls:'pop',noctl:true})+`<div class="link-warning">${W('WARNING',`${TRI}<div class="warnlbl">${s.error?'LOGIN: REJECTED':'NEVER USE YOUR<br>APPLE ID PASSWORD'}<br><span style="font-weight:400;font-size:11px">${s.error?'USE AN APP-SPECIFIC ONE':'ENCRYPTED // REVOCABLE'}</span></div>`,{on:1,cls:'pop warnwin',noctl:true})}</div>`
  return shell('LINK_ICLOUD',['OPEN <a href="https://account.apple.com" target="_blank" rel="noreferrer">account.apple.com</a> //','SIGN-IN & SECURITY → APP PASSWORDS //','+ NAME IT “TERMINAL_MAIL” //','PASTE THE 16-CHAR CODE →'],body,'STEP 2 OF 3',true)
}

export function syncView(s){
  const status=s.sync||{},total=status.total||0,imported=status.imported||0,percent=total?Math.min(100,Math.round(imported/total*100)):0
  const body=W('LOG_VIEWER // IMPORT',`<div class="import-folders">${(s.folderInfo||[]).map(folder=>`<div class="import-folder"><span>${ico(folder.complete?'check':'folder')} ${esc(folder.name)}</span>${prog(folder.total?Math.round(folder.imported/folder.total*100):folder.complete?100:0,{thin:1})}<span>${folder.imported}/${folder.total}</span></div>`).join('')||'<div class="prm"><div>DISCOVERING_MAILBOXES //</div></div>'}</div>`,{on:1,noctl:true})
  const heading=status.ready?'SYSTEM_STATUS: SYNCING<br>INBOX_READY':'SYSTEM_STATUS:<br>CONNECTING'
  let html=shell(heading,[`IMAP_LINK: ${status.mode?'ESTABLISHED':'CONNECTING'} //`,`MODE: ${esc(status.mode||'PENDING')} //`,'HISTORY: BACKFILL IN BACKGROUND'],body,'STEP 3 OF 3')
  html=html.replace('class="scr ','class="scr syncing ')
  const progress=`<div class="import-progress"><div class="import-progress-label"><span class="cap">HEADER_IMPORT_PROGRESS_...</span><b class="mono">${percent}%</b></div>${prog(percent,{style:'height:34px'})}<div class="import-progress-label"><span class="cap mute">${imported.toLocaleString()} / ${total.toLocaleString()} KNOWN HEADERS · BODIES ON DEMAND</span><button class="btn pri" data-a="enter-inbox" ${status.ready?'':'disabled'}>ENTER_INBOX ${K('↵')}</button></div>${status.error?`<div class="form-alert" role="alert">${esc(status.error)} ${button('relink','RELINK ICLOUD')}</div>`:''}</div>`
  return html.replace('<div class="foot">',progress+'<div class="foot">')
}

function sidebar(s) {
  let tree=s.view==='settings'?`<div class="ni" role="button" tabindex="0" data-a="mail">${ico('inbox')} ../MAIL<span class="n">${K('esc')}</span></div><div class="ng">/_settings</div>`+TABS.map(([k,l,i],n)=>`<div class="ni ${s.tab===k?'on':''}" role="button" tabindex="0" data-tab="${k}"><span class="br">${n===TABS.length-1?'└':'├'}</span>${ico(i)}${l}</div>`).join(''):SYSTEM_FOLDERS.map(([k,l,i])=>`<div class="ni ${s.folder===k?'on':''}" role="button" tabindex="0" data-f="${k}">${ico(i)} ${l}${s.counts[k]?`<span class="n">${s.counts[k]}</span>`:''}</div>`).join('')+`<div class="ng">/_folders<span class="sp"></span>${button('new-folder',ico('plus'),'ib')}</div>`+s.folders.filter(f=>role(f)===f).map(f=>`<div class="ni ${s.folder===f?'on':''}" role="button" tabindex="0" data-f="${esc(f)}">${ico('folder')}<span class="folder-name">${esc(f)}</span><span class="sp"></span><button class="ib folder-edit" data-manage-folder="${esc(f)}" aria-label="Manage ${esc(f)}">${ico('gear')}</button></div>`).join('')
  return W(s.view==='settings'?'SETTINGS.SYS':'MAILBOXES.SYS',`<div class="sbtop">${button('compose',`${ico('plus')} COMPOSE<span class="sp"></span>${keyHint(s,'compose')}`,'btn pri wide')}${button('search',`${ico('search')} SEARCH_<span class="sp"></span>${K('/')}`,'sbs')}</div><div class="tree">${tree}</div><div class="sfill"></div><div class="quota">${s.sync?.quota?.limit?`<div class="l"><span>STORAGE</span><span>${(s.sync.quota.used/1073741824).toFixed(1)} / ${(s.sync.quota.limit/1073741824).toFixed(1)} GB</span></div>${prog(Math.min(100,Math.round(s.sync.quota.used/s.sync.quota.limit*100)),{thin:1})}`:''}<div class="l"><span>${ico('agent')} AGENTS</span>${button('settings:agents','MANAGE','link')}</div><div class="l" style="margin-top:2px;color:var(--mute)"><span class="account-address">${esc(s.account.icloud_email)}</span>${button('settings',ico('gear'),'ib')}</div></div>`,{on:s.focus==='side',cls:'side',a:'side'})
}
function row(m,s,i) {
  const picked=s.picked.includes(m.id)
  const terms=searchTokens(s.search||'').filter(token=>!token.includes(':')).map(token=>token.replace(/^"|"$/g,'')),pattern=terms.length?new RegExp('('+terms.map(term=>term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).sort((a,b)=>b.length-a.length).join('|')+')','ig'):null
  const text=value=>pattern?value.split(pattern).map((part,index)=>index%2?'<mark>'+esc(part)+'</mark>':esc(part)).join(''):esc(value)
  return `<div class="row-wrap ${s.swipeID===m.id?'swiped':''}"><button type="button" class="swipe-archive" data-a="archive" data-message-index="${i}" aria-label="Archive ${esc(m.subj)}">${ico('archive')} ARCHIVE</button><div class="row ${m.pendingLocation?'location-pending':''} ${m.un?'un':''} ${i===s.cur?'cur':''} ${s.picked.length?'sel':''} ${picked?'picked':''}" data-i="${i}" data-id="${esc(m.id)}" role="option" aria-selected="${picked||i===s.cur}" aria-busy="${!!m.pendingLocation}" tabindex="${i===s.cur?'0':'-1'}" draggable="true"><div class="mk">${s.picked.length?`<span class="chk ${picked?'on':''}"></span>`:''}</div><div class="l1"><span class="who">${esc(m.who)}</span>${m.actor?.startsWith('mcp:')?`<span class="tag" title="${esc(agentName(s,m.actor))}">${ico('agent')} AGENT</span>`:''}${m.n>1?`<span class="cnt">[${m.n}]</span>`:''}${m.f==='drafts'?'<span class="tag">[DRAFT]</span>':''}<span class="meta">${m.att?ico('clip'):''}${COLORS.includes(m.fl)?`<span class="flag ${m.fl}"></span>`:''}${m.f==='snoozed'?`${ico('clock')} ${m.snoozeUntil?esc(new Date(m.snoozeUntil).toLocaleDateString([],{month:'short',day:'numeric'})):'—'}`:esc(m.t)}</span></div><div class="l2"><b>${text(m.subj)}</b> · ${text(m.snip)}</div><div class="qa">${[['archive','e'],['snooze','h'],['flag','s'],['trash','#']].map(([a,key])=>`<button class="ib" data-a="${a}" aria-label="${a}" title="${a} ${key}">${ico(a==='snooze'?'clock':a)}</button>`).join('')}</div></div></div>`
}
function list(s) {
  const rows=visible(s), title=s.search?`SEARCH // ${rows.length} RESULTS`:`${esc(s.folder.toUpperCase())} // ${s.total} MSG // ${rows.filter(m=>m.un).length} UNREAD`
  let ph=s.picked.length?`<div class="ph" style="background:var(--acc);color:var(--acc-ink)"><span class="chk on" style="margin-left:6px"></span><span class="cap">${s.picked.length} SELECTED</span><span class="sp"></span><span class="cap" style="font-size:10px">E ARCHIVE · # TRASH · V MOVE · ESC CLEAR</span></div>`:s.overlay==='search'?`<div class="ph">${ico('search')}<span class="mono mute">&gt;&gt;</span><input id="sq" aria-label="Search mail" value="${esc(s.q)}" placeholder="from: has:attachment after: in:" autocomplete="off">${button('clear-search',K('esc'),'ib')}</div>`:s.search?`<div class="ph search-chips">${searchTokens(s.search).map((token,index)=>`<button class="chip ${token.includes(':')?'inv':''}" data-search-remove="${index}" aria-label="Remove ${esc(token)}">${esc(token)} ×</button>`).join('')}<span class="sp"></span>${button('search',ico('search'),'ib')}<span class="cap mute search-time">LOCAL ${s.searchInfo?.localMS||0}MS${s.searchInfo?.bodyMS!==null&&s.searchInfo?.bodyMS!==undefined?' · CACHE '+s.searchInfo.bodyMS+'MS':''}${s.searchInfo?.server?' · SERVER '+(s.searchInfo.server.running?'…':s.searchInfo.server.ms+'MS'):''}</span>${button('clear-search',K('esc'),'ib')}</div>`:`<div class="ph"><div class="seg" role="group" aria-label="Filter messages">${[['all','ALL'],['unread','UNREAD'],['flagged','FLAGGED'],['att','FILES']].map(([k,l])=>`<button class="${s.filter===k?'on':''}" data-filter="${k}">${l}</button>`).join('')}</div><span class="sp"></span>${button('select',ico('check'),'ib')}</div>`
  if(!s.picked.length&&!s.search&&s.overlay!=='search')ph=ph.replace('class="ph"','class="ph list-filterbar"').replace('<span class="sp"></span>',`<span class="sp"></span><details class="phone-only phone-more"><summary aria-label="More message controls">${ico('down')}</summary><div>${button('filter-files','FILES','link')}${button('move','MOVE TO','link')}${button('flagc','FLAG COLOR','link')}${button('read','MARK READ','link')}${button('unread','MARK UNREAD','link')}${button('select','SELECT','link')}</div></details>${button('search',ico('search'),'ib phone-only')}`)
  const body=messageRows(s,rows)
  return W(title,ph+(s.searchInfo?.server?.error?`<div class="lnote" role="status">${esc(s.searchInfo.server.error)} ${button('search-retry','RETRY','link')}</div>`:'')+(s.offline?`<div class="lnote">${ico('wifi')} OFFLINE // ${s.pending} CHANGES QUEUED //</div>`:'')+`<div class="rows" role="listbox" aria-label="Messages" aria-multiselectable="true">${body}</div>`,{on:s.focus==='list',cls:'list',a:'list'})
}
export function messageRows(s,rows=visible(s)) {
  const window=listWindow(rows,s)
  let body=`<div aria-hidden="true" style="height:${window.before}px"></div>`
  for(const item of window.items){const m=rows[item.index];if(item.day)body+=`<div class="day">${esc(m.day)}</div>`;body+=row(m,s,item.index)}
  body+=`<div aria-hidden="true" style="height:${window.after}px"></div>`
  if(!rows.length)body=`<div class="empty dots" style="height:100%">${W(`${esc(s.folder.toUpperCase())}.STATUS`,`<div class="empty-status"><div class="disp" style="font-size:22px">${s.loading?'LOADING_MAIL':s.error?'SYNC: FAILED':s.search?'NO_MATCH':`${esc(s.folder.toUpperCase())}: EMPTY`}</div><div class="prm"><div>${s.loading?'FETCHING_FROM_ICLOUD //':s.error?esc(s.error):'NOTHING_PENDING //'}</div></div>${s.error?button('refresh','TRY AGAIN'):prog(s.loading?0:100,{thin:1})}</div>`,{cls:'pop',noctl:true})}</div>`
  return body+(s.msgs.length<(s.loaded??s.total)?`<div class="load-more">${button('load-more',s.loading?'LOADING…':'LOAD MORE')}</div>`:'')
}
export function paintSelection(root,s) {
  const list=root.querySelector('.rows')
  if(!list||!root.querySelector('.reader'))return false
  if(!list.querySelector(`[data-i="${s.cur}"]`))morph(list,messageRows(s))
  for(const row of list.querySelectorAll('.row')){
    const selected=Number(row.dataset.i)===s.cur
    row.classList.toggle('cur',selected)
    row.tabIndex=selected?0:-1
    row.setAttribute('aria-selected',String(selected||s.picked.includes(row.dataset.id)))
  }
  list.scrollTop=s.listScroll||0
  root.querySelector('.reader').outerHTML=reader(s)
  return true
}
export function emailDocument(html, dark=false,font='sans',fonts={},original=false) {
  const csp=`<meta charset="utf-8"><meta name="referrer" content="no-referrer"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; font-src data:; img-src data:; form-action 'none'; base-uri 'none'">`
  // Original mode keeps the sender's own look: no theme colors or reader font, on the white page senders design for.
  if(original)return `<!doctype html><html><head>${csp}<style>:root{color-scheme:light}body{margin:8px;background:#fff;color:#000}img{max-width:100%;height:auto}</style></head><body>${html}</body></html>`
  const name=font==='mono'?'IBM Plex Mono':'IBM Plex Sans',data=fonts[font==='mono'?'mono':'sans']
  return `<!doctype html><html><head>${csp}<style>${data?`@font-face{font-family:'${name}';src:url('${data}') format('truetype')}`:''}:root{color-scheme:${dark?'dark':'light'}}body{margin:0;font:15px/1.75 '${name}',${font==='mono'?'monospace':'sans-serif'};overflow-wrap:anywhere;color:${dark?'#E6E6E0':'#141413'};background:transparent}img{max-width:100%}a{color:inherit}pre{white-space:pre-wrap}table{max-width:100%}</style></head><body>${html}</body></html>`
}
function reader(s) {
  const m=current(s)
  if(!m)return W('MESSAGE_VIEWER',`<div class="empty dots"><span class="cap mute">NO_MESSAGE_SELECTED // PRESS ${K('j')}</span></div>`,{cls:'reader',a:'reader'})
  const tb=`<div class="ph phone-only phone-reader-toolbar">${button('back','← INBOX','tk')}${m.f==='drafts'?button('edit-draft','EDIT','btn sm'):''}<span class="sp"></span>${[['archive','archive'],[m.f==='snoozed'?'unsnooze':'snooze','clock'],['flag','flag'],['trash','trash']].map(([action,icon])=>`<button type="button" class="ib" data-a="${action}" aria-label="${action}">${ico(icon)}</button>`).join('')}</div><div class="ph reader-toolbar desktop-only">${m.f==='snoozed'?button('unsnooze',`${ico('clock')} RETURN`,'tk'):''}${m.f==='drafts'?button('edit-draft','EDIT DRAFT','btn pri sm'):''}${[['archive','e','ARCHIVE'],['snooze','h','SNOOZE'],['move','v','MOVE'],['flag','s','FLAG'],['trash','#','TRASH']].map(([a,k,l])=>button(a,`${keyHint(s,a)} ${l}`,'tk')).join('')}<span class="sp"></span>${button('prev',ico('up'),'ib')}${button('next',ico('down'),'ib')}</div>`
  const thread=m.threadMessages?.map(raw=>message(raw,raw.folder))||[m],expanded=s.expandedThread===m.threadId
  const head=`<div class="rhead crop"><h1 class="subj">${esc(m.subj)}</h1><div class="prm" style="color:var(--ink-2)"><div>${thread.length} MESSAGE${thread.length===1?'':'S'} // FOLDER: ${esc(m.folder)} // ${m.snoozed?`SNOOZED_UNTIL: ${m.snoozeUntil?esc(new Date(m.snoozeUntil).toLocaleString()):'SOMEDAY'} // `:''}${m.sentBy?`SENT_BY: ${esc(agentName(s,m.sentBy))} // `:''}${m.fl?`FLAG: <span class="flag ${m.fl}"></span> ${m.fl.toUpperCase()} //`:''}</div></div></div>`
  const renderMessage=(x,i)=>{
    const e=s.bodies[x.bodyKey||x.id],open=expanded||i===thread.length-1||s.openMessages?.includes(x.key)
    if(!open)return `<button class="tm c thread-message" data-thread-message="${esc(x.key)}"><span class="av">${esc(ini(x.who))}</span><span class="w">${esc(x.who)}</span><span class="s">${esc(x.snip)}</span><span class="d">${esc(x.t)}</span></button>`
    const body=e?!e.bodyHTML?`<div class="body plain-body">${esc(e.bodyPlain)}</div>`:`<iframe class="email-frame${s.prefs.remoteContent==='original'?' original':''}" title="Email message" sandbox="allow-popups allow-popups-to-escape-sandbox" referrerpolicy="no-referrer" srcdoc="${esc(emailDocument(e.displayHTML??e.bodyHTML??'',s.theme==='dark',s.prefs.readingFont,s.readerFonts,s.prefs.remoteContent==='original'))}"></iframe>`:`<div class="body prm mute"><div>${x.pendingLocation?'LOCATION_CHANGE_PENDING //':s.bodyError?esc(s.bodyError):'LOADING_MESSAGE //'}</div>${s.bodyError?button('retry-body','RETRY'):''}</div>`
    const files=(e?.attachments||[]).map(a=>`<a class="file" data-attachment="${esc(a.filename)}" href="/api/mail/attachment?${esc(new URLSearchParams({folder:x.folder,id:x.uid,validity:x.uidValidity,filename:a.filename}).toString())}" target="_blank" rel="noreferrer"><div class="pv dots"></div><div class="nm"><span>${esc(a.filename)}</span><span class="z">${Math.ceil(a.size/1024)}K</span></div></a>`).join('')
    return `<div class="tm e" data-thread-key="${esc(x.key)}"><div class="h"><span class="av">${esc(ini(x.who))}</span><div><div class="w">${esc(x.who)}</div><div class="a"><span class="desktop-only">${esc(x.em)} → ${esc((e?.to||x.to||[]).join(', '))}</span><span class="phone-only">${esc(x.t)} → ${esc((e?.to||x.to||[]).map(address=>address.includes(s.account.icloud_email)?'me':address).join(', '))}</span></div></div><span class="d">${esc(x.t)}</span></div>${body}${e?.remoteImages?.length?`<div class="notice">${ico('eye')} REMOTE_CONTENT: ${e.remoteLoading?'LOADING':Object.keys(e.loadedImages||{}).length===e.remoteImages.length?'PROXIED':'BLOCKED'} // ${e.trackersStripped||0} TRACKERS STRIPPED<span class="sp"></span><button class="link" data-remote="${esc(x.id)}" ${e.remoteLoading?'disabled':''}>${e.remoteLoading?'LOADING…':e.remoteError?'RETRY VIA PROXY':'LOAD VIA PROXY'}</button></div>${e.remoteError?`<div role="alert" class="form-alert">${esc(e.remoteError)}</div>`:''}`:e?.trackersStripped?`<div class="notice">${ico('eye')} ${e.trackersStripped} TRACKERS STRIPPED</div>`:''}${files&&!x.pendingLocation?`<div class="files">${files}</div>`:''}</div>`
  }
  const more=thread.length>1?button('expand-thread',`${ico('mail')} ${expanded?'COLLAPSE THREAD':`${thread.length-1} EARLIER MESSAGE${thread.length>2?'S':''}`} // ${K(';')}`,'more'):''
  const content=`<div class="rc ${s.compose==='inline'?'has-reply':''}"><div class="rin">${head}${m.snoozeError?`<div class="notice form-alert" role="alert">${ico('warn')} ${esc(m.snoozeError)}</div>`:''}${m.listId?`<div class="notice">${ico('mail')} MAILING_LIST: ${esc(m.listId)}<span class="sp"></span>${unsubscribeLinks(m.unsubscribe).length?button('unsubscribe','UNSUBSCRIBE','link'):''}</div>`:''}${more}${thread.map(renderMessage).join('')}</div></div>`
  const reply=s.compose==='inline'?`<div class="qr open">${W('REPLY // '+esc(m.who.toUpperCase()),composeForm(s),{on:1,a:'compose'})}</div>`:`<div class="qr">${button('reply',`${ico('reply')} &gt;&gt; REPLY_TO_${esc(m.who.split(' ')[0].toUpperCase())}`,'reply-action')}<span class="sp"></span>${button('reply-all',`${K('a')} ALL`,'link')}${button('forward',`${K('f')} FWD`,'link')}</div>`
  return W(`MESSAGE_VIEWER // <span class="dm" style="font-size:13px">${String(s.cur+1).padStart(2,'0')}/${String(visible(s).length).padStart(2,'0')}</span>`,tb+content+reply,{on:s.focus==='reader',cls:'reader',a:'reader'})
}
